// cartSlice.js - Redux Toolkit implementation
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import api from '../services/api';

export const syncCartItem = createAsyncThunk(
  'cart/syncItem',
  async ({ productId, quantity, variantId }, { rejectWithValue }) => {
    try {
      const response = await api.post('/cart/update', { productId, quantity, variantId });
      return response.data; // Updated server cart
    } catch (err) {
      return rejectWithValue(err.response?.data || 'Failed to sync cart');
    }
  }
);

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: {}, status: 'idle', totalAmount: 0 },
  reducers: {
    optimisticUpdate: (state, action) => {
      const { id, quantity } = action.payload;
      if (state.items[id]) state.items[id].quantity = quantity;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(syncCartItem.fulfilled, (state, action) => {
        state.items = action.payload.items;
        state.totalAmount = action.payload.totalAmount;
      });
  }
});

// middleware/auth.js - Express RBAC Guard
import jwt from 'jsonwebtoken';

export const verifyAuth = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, message: 'Access token required' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded; // { userId, role, assignedHub }
    next();
  } catch (error) {
    return res.status(403).json({ success: false, message: 'Invalid or expired token' });
  }
};

export const authorizeRoles = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        message: 'Permission denied: Insufficient privileges for this action'
      });
    }
    next();
  };
};

// parcelAnalytics.js - Optimized Aggregation Pipeline
const getHubDeliverySummary = async (hubId, startDate, endDate) => {
  return await Parcel.aggregate([
    // Stage 1: Filter early using compound index (assignedHub + createdAt)
    {
      $match: {
        assignedHub: new mongoose.Types.ObjectId(hubId),
        createdAt: { $gte: new Date(startDate), $lte: new Date(endDate) }
      }
    },
    // Stage 2: Project only required fields to minimize memory footprint
    {
      $project: {
        trackingNumber: 1,
        status: 1,
        riderId: 1,
        deliveryPincode: 1
      }
    },
    // Stage 3: Group by status and count
    {
      $group: {
        _id: '$status',
        totalCount: { $sum: 1 },
        parcels: { $push: '$trackingNumber' }
      }
    }
  ]);
};

// AppRouter.jsx - Route-Based Lazy Loading
import React, { Suspense, lazy } from 'react';
import LoadingSpinner from './components/LoadingSpinner';

const HomePage = lazy(() => import('./pages/HomePage'));
const ProductDetails = lazy(() => import('./pages/ProductDetails'));
const CourierTracker = lazy(() => import('./pages/CourierTracker'));

export const AppRouter = () => (
  <Suspense fallback={<LoadingSpinner message="Loading application..." />}>
    <Routes>
      <Route path="/" element={<HomePage />} />
      <Route path="/product/:id" element={<ProductDetails />} />
      <Route path="/track/:code" element={<CourierTracker />} />
    </Routes>
  </Suspense>
);
